SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('e512054c-240f-461d-9ccd-e6cc5c9e6411', 'advanced', 'multiple_choice', 'A technical yarn engineer explains that a ''balanced'' cabled yarn construction (where the FINAL cable twist direction is chosen to counteract the cumulative residual torque from BOTH the singles twist AND the intermediate ply twist) is critical for rope/cordage applications. Why does an UNBALANCED multi-stage twisted construction (where residual torque from each stage simply accumulates rather than being deliberately counteracted) cause a specific functional problem in a LONG rope under load?', '["Unbalanced twist construction has no functional consequence for rope applications, making twist-balance considerations unnecessary for any cordage product","An unbalanced construction retains significant cumulative residual torque, which under sustained load (especially in a long rope) causes the rope to visibly TWIST/ROTATE and potentially KINK or hockle (form tight, damaging loops) as it attempts to release that stored torque — a properly balanced multi-stage construction (each stage''s twist direction chosen to counteract the previous stage''s residual torque) minimizes this stored torque, keeping the rope torque-neutral and stable under load, directly extending the earlier single-stage plying-twist-balance discussion to a MULTI-stage cabled construction","Twist balance only matters for very short yarn lengths, becoming completely irrelevant for long rope/cordage applications, the opposite of the actual relationship between rope length and torque-balance importance","A cabled rope construction can never retain any residual torque regardless of how each individual twisting stage''s direction is chosen, making balance considerations technically unnecessary"]'::jsonb, 'An unbalanced construction retains significant cumulative residual torque, which under sustained load (especially in a long rope) causes the rope to visibly TWIST/ROTATE and potentially KINK or hockle (form tight, damaging loops) as it attempts to release that stored torque — a properly balanced multi-stage construction (each stage''s twist direction chosen to counteract the previous stage''s residual torque) minimizes this stored torque, keeping the rope torque-neutral and stable under load, directly extending the earlier single-stage plying-twist-balance discussion to a MULTI-stage cabled construction', 'This extends the earlier single-stage plying-twist-balance principle (why ply twist direction is chosen opposite to singles twist direction) to a MULTI-stage cabled construction — just as unbalanced single-stage twist creates instability/snarling risk, an unbalanced multi-stage cabled construction retains cumulative residual torque across ALL its twisting stages, and under sustained load (particularly relevant for long ropes, which have more accumulated torque and more physical length over which it can express itself), this stored torque causes the rope to visibly twist/rotate or even form damaging kinks (hockles) as it seeks to release that torque — deliberately balancing each stage''s twist direction against the cumulative torque from previous stages (not just the immediately-preceding one) is what keeps a multi-stage cabled rope construction genuinely torque-neutral and stable under real working load.', 3, '{"multi-stage-torque-balance"}'::text[]),
('e512054c-240f-461d-9ccd-e6cc5c9e6411', 'advanced', 'multiple_choice', 'A yarn manufacturer''s technical bulletin distinguishes ''nominal'' draw ratio (the machine''s SET target draw ratio) from ''actual'' draw ratio (independently VERIFIED by measuring the true length change between feed and delivery points). If a machine''s nominal draw ratio is set to 4.2× but independent verification measures the ACTUAL ratio at 4.05×, what does this GAP most likely indicate, and why does it matter for the resulting filament''s properties?', '["This gap has no practical significance and can be safely ignored, since nominal and actual draw ratio are always mathematically guaranteed to be identical regardless of any real-world process factors","The gap likely indicates some SLIPPAGE occurring at the feed or delivery rollers (the filament not being gripped/driven with perfect precision, a genuine mechanical imperfection) — since draw ratio directly determines molecular orientation and therefore tenacity/elongation (as established earlier), this gap means the filament''s ACTUAL achieved properties will differ from what the nominal machine setting alone would predict, making independent verification (not just trusting the machine''s nominal setting) important for genuine quality assurance","A gap between nominal and actual draw ratio always indicates the raw polymer material itself is defective, with zero possible mechanical/process explanation","Nominal draw ratio is always more accurate and reliable than any independently measured actual draw ratio, making verification measurement an unnecessary quality control step"]'::jsonb, 'The gap likely indicates some SLIPPAGE occurring at the feed or delivery rollers (the filament not being gripped/driven with perfect precision, a genuine mechanical imperfection) — since draw ratio directly determines molecular orientation and therefore tenacity/elongation (as established earlier), this gap means the filament''s ACTUAL achieved properties will differ from what the nominal machine setting alone would predict, making independent verification (not just trusting the machine''s nominal setting) important for genuine quality assurance', 'This directly extends the earlier draw-ratio/molecular-orientation/tenacity discussion with a practical process-verification insight — a genuine gap between the machine''s NOMINAL (set/intended) draw ratio and the INDEPENDENTLY VERIFIED actual draw ratio most likely indicates roller SLIPPAGE (the filament isn''t being gripped and driven with perfect precision at the feed/delivery points, a real mechanical imperfection) — since draw ratio is the direct determinant of molecular orientation and therefore tenacity/elongation, this gap means the filament''s TRUE achieved properties will differ from what simply trusting the machine''s nominal setting would predict, which is exactly why serious quality assurance requires independently VERIFYING actual draw ratio (and resulting properties) rather than assuming the machine''s programmed setting was achieved perfectly.', 3, '{"nominal-vs-actual-draw-ratio"}'::text[]);
COMMIT;
